import{_ as a,o as p,a as n,b as c}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/src_dst_bitwidth_1to2.B-0d1EVF.png",t="/ascendc.github.io/assets/src_dst_bitwidth_2to1.DmYnFazq.png",i="/ascendc.github.io/assets/src_dst_bitwidth_1to4.DyQWfZ16.png",e="/ascendc.github.io/assets/src_dst_bitwidth_4to1.JogIgmpK.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Reg矢量计算","link":"/api/SIMD-API/basic_api/reg_vector_compute/reg_vector_compute"},{"text":"辅助数据类型","link":"/api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/aux_data_types"},{"text":"RegLayout","link":"/api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RegLayout"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RegLayout.md","filePath":"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RegLayout.md","lastUpdated":1786019781000}'),o={name:"api/SIMD-API/basic_api/reg_vector_compute/aux_data_types/RegLayout.md"};function _(d,s,m,r,u,g){return p(),n("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>RegLayout<span id="ZH-CN_TOPIC_0000001956862301"></span></h1><p>源操作数和目的操作数位宽不同时，单条指令计算量以位宽更大的数据类型为准，RegLayout用于控制位宽小的元素在寄存器中的排布方式。更多特性说明请参考<a href="../type_conversion/Cast.html">Cast</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">enum</span><span class="w"> </span><span class="k">class</span><span class="w"> </span><span class="nc">RegLayout</span><span class="w"> </span><span class="p">{</span><span class="w"> </span>
<span class="w">    </span><span class="n">UNKNOWN</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">-1</span><span class="p">,</span><span class="w"> </span>
<span class="w">    </span><span class="n">ZERO</span><span class="p">,</span><span class="w">         </span><span class="c1">// 大转小（dst位宽小）：结果位于dst组内第0个位宽小位置；小转大（src位宽小）：选取src组内第0个位宽小元素</span>
<span class="w">    </span><span class="n">ONE</span><span class="p">,</span><span class="w">          </span><span class="c1">// 大转小（dst位宽小）：结果位于dst组内第1个位宽小位置；小转大（src位宽小）：选取src组内第1个位宽小元素</span>
<span class="w">    </span><span class="n">TWO</span><span class="p">,</span><span class="w">          </span><span class="c1">// 大转小（dst位宽小）：结果位于dst组内第2个位宽小位置；小转大（src位宽小）：选取src组内第2个位宽小元素</span>
<span class="w">    </span><span class="n">THREE</span><span class="w">         </span><span class="c1">// 大转小（dst位宽小）：结果位于dst组内第3个位宽小位置；小转大（src位宽小）：选取src组内第3个位宽小元素</span>
<span class="p">};</span>
</code></pre></div><p>源操作数与目的操作数类型位宽不同时，可以分为四种情况，用户可以根据实际场景选择对应的RegLayout，其中，mask的有效情况均以输入数据位宽为准。</p><ul><li><p>源操作数与目的操作数位宽比为1:2。</p><p>例如，ExpSub接口输入数据类型为half(b16)，输出数据类型为float(b32)时，mask每2位有效，RegLayout确定源操作数中，每2个half类型数据参与计算的数据的位置。</p><p><a id="fig1"></a></p><p><img src="`+l+'" alt title="源操作数与目的操作数位宽比为1:2"></p></li><li><p>源操作数与目的操作数位宽比为2:1。</p><p>例如，Cast接口输入数据类型为float(b32)，输出数据类型为half(b16)，mask每4位有效，RegLayout确定目的操作数中，每2个half类型数据有效数据的位置。</p><p><a id="fig2"></a></p><p><img src="'+t+'" alt title="源操作数与目的操作数位宽比为2:1"></p></li><li><p>源操作数与目的操作数位宽比为1:4。</p><p>例如，Cast接口输入数据类型为int8_t(b8)，输出数据类型为int32_t(b32)，mask每1位有效，RegLayout确定源操作数中，每4个int8_t类型数据参与计算的数据的位置。</p><p><a id="fig3"></a></p><p><img src="'+i+'" alt title="源操作数与目的操作数位宽比为1:4"></p></li><li><p>源操作数与目的操作数位宽比为4:1。</p><p>例如，Cast接口输入数据类型为int32_t(b32)，输出数据类型为uint8_t(b8)，mask每4位有效，RegLayout确定目的操作数中，每4个uint8_t类型数据有效数据的位置。</p><p><a id="fig4"></a></p><p><img src="'+e+`" alt title="源操作数与目的操作数位宽比为4:1"></p></li></ul><p>Cast在不同RegLayout取值下的数据排布伪代码如下，其中layout参数与枚举值的映射关系为：0对应RegLayout::ZERO，1对应RegLayout::ONE，2对应RegLayout::TWO，3对应RegLayout::THREE：</p><div class="code-block"><div class="code-header"><span class="lang-label">Python</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kn">import</span><span class="w"> </span><span class="nn">numpy</span><span class="w"> </span><span class="k">as</span><span class="w"> </span><span class="nn">np</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每4bit最低位为1时选取对应位置的b32元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b32_to_b16</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[:]</span> <span class="o">=</span> <span class="mi">0</span>
    <span class="n">dst</span><span class="p">[</span><span class="n">layout</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">64</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">int16</span><span class="p">)</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每2bit最低位为1时选取对应位置的b16元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b16_to_b32</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">64</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="n">layout</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">int32</span><span class="p">)</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每4bit最低位为1时选取对应位置的b32元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b32_to_b8</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[:]</span> <span class="o">=</span> <span class="mi">0</span>
    <span class="n">dst</span><span class="p">[</span><span class="n">layout</span><span class="p">:</span><span class="mi">256</span><span class="p">:</span><span class="mi">4</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">64</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">uint8</span><span class="p">)</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每1bit为1时选取对应位置的b8元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b8_to_b32</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">64</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="n">layout</span><span class="p">:</span><span class="mi">256</span><span class="p">:</span><span class="mi">4</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">int32</span><span class="p">)</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每4bit最低位为1时选取对应位置连续的两个b16元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b16_to_b4</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[:]</span> <span class="o">=</span> <span class="mi">0</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">2</span><span class="o">*</span><span class="n">layout</span>    <span class="p">:</span> <span class="mi">512</span> <span class="p">:</span> <span class="mi">8</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">uint8</span><span class="p">)</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">2</span><span class="o">*</span><span class="n">layout</span> <span class="o">+</span> <span class="mi">1</span><span class="p">:</span> <span class="mi">512</span> <span class="p">:</span> <span class="mi">8</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">1</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">uint8</span><span class="p">)</span>

<span class="c1"># MaskReg行为：MaskReg长度为256bit，每1bit为1时选取对应位置连续的两个b4元素进行转换。</span>
<span class="k">def</span><span class="w"> </span><span class="nf">cast_b4_to_b16</span><span class="p">(</span><span class="n">src</span><span class="p">,</span> <span class="n">dst</span><span class="p">,</span> <span class="n">layout</span><span class="p">):</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">0</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">2</span><span class="o">*</span><span class="n">layout</span>    <span class="p">:</span> <span class="mi">512</span> <span class="p">:</span> <span class="mi">8</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">int16</span><span class="p">)</span>
    <span class="n">dst</span><span class="p">[</span><span class="mi">1</span><span class="p">:</span><span class="mi">128</span><span class="p">:</span><span class="mi">2</span><span class="p">]</span> <span class="o">=</span> <span class="n">src</span><span class="p">[</span><span class="mi">2</span><span class="o">*</span><span class="n">layout</span> <span class="o">+</span> <span class="mi">1</span><span class="p">:</span> <span class="mi">512</span> <span class="p">:</span> <span class="mi">8</span><span class="p">]</span><span class="o">.</span><span class="n">astype</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">int16</span><span class="p">)</span>
</code></pre></div></article></div>`,1)])])}const y=a(o,[["render",_]]);export{h as __pageData,y as default};
